    "kernel_code": "1: import numpy as np\n2: import torch\n3: import triton\n4: import triton.language as tl\n5: \n6: \n7: @triton.jit\n8: def _fit_predict(X, Y, Q, Out, N: tl.constexpr):\n9:     s0 = tl.full((), 0.0, tl.float32)\n10:     s1 = tl.full((), 0.0, tl.float32)\n11:     sy = tl.full((), 0.0, tl.float32)\n12:     s00 = tl.full((), 0.0, tl.float32)\n13:     s01 = tl.full((), 0.0, tl.float32)\n14:     s11 = tl.full((), 0.0, tl.float32)\n15:     s0y = tl.full((), 0.0, tl.float32)\n16:     s1y = tl.full((), 0.0, tl.float32)\n17:     for i in tl.static_range(N):\n18:         x0 = tl.load(X + 2 * i)\n19:         x1 = tl.load(X + 2 * i + 1)\n20:         val = tl.load(Y + i)\n21:         s0 = s0 + x0\n22:         s1 = s1 + x1\n23:         sy = sy + val\n24:         s00 = s00 + x0 * x0\n25:         s01 = s01 + x0 * x1\n26:         s11 = s11 + x1 * x1\n27:         s0y = s0y + x0 * val\n28:         s1y = s1y + x1 * val\n29:     m0 = s0 / N\n30:     m1 = s1 / N\n31:     my = sy / N\n32:     a = (s00 / N - m0 * m0) + 0.0009765625\n33:     b = s01 / N - m0 * m1\n34:     c = (s11 / N - m1 * m1) + 0.0009765625\n35:     u = s0y / N - m0 * my\n36:     v = s1y / N - m1 * my\n37:     det = a * c - b * b\n38:     beta0 = tl.div_rn(c * u - b * v, det)\n39:     beta1 = tl.div_rn(a * v - b * u, det)\n40:     rows = tl.arange(0, 4)\n41:     q0 = tl.load(Q + rows * 2)\n42:     q1 = tl.load(Q + rows * 2 + 1)\n43:     result = (my + (q0 - m0) * beta0) + (q1 - m1) * beta1\n44:     tl.store(Out + rows, result)\n45: \n46: \n47: def run(x, y, q):\n48:     output = torch.empty((4,), device=x.device, dtype=torch.float32)\n49:     _fit_predict[(1,)](x, y, q, output, N=32, num_warps=1,\n50:                       enable_fp_fusion=False)\n51:     return output\n52: \n53: \n54: def make_inputs_numpy():\n55:     rng = np.random.Generator(np.random.PCG64(130555))\n56:     latent = rng.normal(0.0, 0.0625, (32, 2))\n57:     x = (np.asarray([32.0, -24.0]) + latent).astype(np.float32)\n58:     y = (latent @ np.asarray([0.75, -1.25]) +\n59:          rng.normal(0.0, 0.015625, 32)).astype(np.float32)\n60:     q = (np.asarray([32.0, -24.0]) +\n61:          rng.normal(0.0, 0.25, (4, 2))).astype(np.float32)\n62:     return x, y, q\n63: \n64: \n65: def make_inputs(device=\"cuda\"):\n66:     return tuple(torch.from_numpy(array).to(device) for array in make_inputs_numpy())\n67: \n68: \n69: def initial_probe():\n70:     x, y, q = make_inputs()\n71:     actual = run(x, y, q)\n72:     stats = torch.zeros((8,), dtype=torch.float32, device=x.device)\n73:     for i in range(32):\n74:         x0, x1, yi = x[i, 0], x[i, 1], y[i]\n75:         stats = stats + torch.stack((x0, x1, yi, x0*x0, x0*x1,\n76:                                       x1*x1, x0*yi, x1*yi))\n77:     m0, m1, my, second00, second01, second11, cross0, cross1 = stats / 32\n78:     cov00 = second00 - m0*m0 + 1/1024\n79:     cov01 = second01 - m0*m1\n80:     cov11 = second11 - m1*m1 + 1/1024\n81:     rhs0, rhs1 = cross0 - m0*my, cross1 - m1*my\n82:     determinant = cov00*cov11 - cov01*cov01\n83:     b0 = (cov11*rhs0 - cov01*rhs1) / determinant\n84:     b1 = (cov00*rhs1 - cov01*rhs0) / determinant\n85:     expected = (my + (q[:, 0]-m0)*b0) + (q[:, 1]-m1)*b1\n86:     error = torch.linalg.vector_norm(actual.double()-expected.double()) / torch.clamp(\n87:         torch.linalg.vector_norm(expected.double()), min=0.1)\n88:     return {\"output\": actual.detach().cpu().tolist(),\n89:             \"reference\": expected.detach().cpu().tolist(),\n90:             \"relative_error\": float(error.item()),\n91:             \"tolerance\": 0.05, \"passed\": bool(error.item() <= 0.05)}",
